#include <iostream>
#include <cstring>
#include <cctype>
#include <vector>
#include <queue>
#include <climits>
using namespace std;

const int dirs[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
const int MAXN = 20;
const int MAXNODES = 1000;
const int MAXEDGES = 2000000;

struct FlowEdge {
    int to;
    int cap;
    int rev_idx;
};

vector<FlowEdge> graph[MAXNODES];
int S, T, n_grid, t_limit, INF_VAL;
int dist_map[MAXN][MAXN];
int dep_map[MAXN][MAXN];
int node_ids[MAXN][MAXN];
int sink_ids[MAXN][MAXN];
char mazeA[MAXN][MAXN];
char mazeB[MAXN][MAXN];

void link_nodes(int u, int v, int cap) {
    graph[u].push_back({v, cap, (int)graph[v].size()});
    graph[v].push_back({u, 0, (int)graph[u].size() - 1});
}

void bfs_expand(int sx, int sy, bool phase2) {
    vector<pair<int,int>> q;
    q.emplace_back(sx, sy);

    memset(dist_map, 0x3f, sizeof(dist_map));
    INF_VAL = dist_map[0][0];
    dist_map[sx][sy] = 0;

    for (int i = 0; i < (int)q.size(); ++i) {
        int x = q[i].first, y = q[i].second;

        if (phase2 && sink_ids[x][y] && dist_map[x][y] <= t_limit && dist_map[x][y] <= dep_map[x][y]) {
            link_nodes(node_ids[x][y], sink_ids[x][y], INF_VAL);
        }

        if (dist_map[x][y] > t_limit || dist_map[x][y] >= dep_map[x][y]) continue;

        if (node_ids[x][y] == 3 && sink_ids[x][y] == 9) {
            printf("%d\n", dist_map[x][y]);
        }

        for (int k = 0; k < 4; ++k) {
            int nx = x + dirs[k][0];
            int ny = y + dirs[k][1];
            if (nx >= 1 && nx <= n_grid && ny >= 1 && ny <= n_grid && isdigit(mazeA[nx][ny]) && dist_map[nx][ny] == INF_VAL) {
                dist_map[nx][ny] = dist_map[x][y] + 1;
                q.emplace_back(nx, ny);
            }
        }
    }
}

bool level_bfs() {
    vector<int> lvl(MAXNODES, 0);
    queue<int> q;
    q.push(S);
    lvl[S] = 1;

    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (auto& e : graph[u]) {
            if (lvl[e.to] == 0 && e.cap > 0) {
                lvl[e.to] = lvl[u] + 1;
                q.push(e.to);
                if (e.to == T) return true;
            }
        }
    }
    return false;
}

int dfs_flow(int u, int flow) {
    if (u == T) return flow;
    for (auto& e : graph[u]) {
        if (e.cap > 0 && lvl[e.to] == lvl[u] + 1) {
            int pushed = dfs_flow(e.to, min(flow, e.cap));
            if (pushed) {
                e.cap -= pushed;
                graph[e.to][e.rev_idx].cap += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, t;
    cin >> n >> t;
    n_grid = n;
    t_limit = t;

    for (int i = 1; i <= n; i++) {
        string line;
        cin >> line;
        for (int j = 0; j < n; j++) {
            mazeA[i][j+1] = line[j];
        }
    }

    for (int i = 1; i <= n; i++) {
        string line;
        cin >> line;
        for (int j = 0; j < n; j++) {
            mazeB[i][j+1] = line[j];
        }
    }

    memset(dep_map, 0x3f, sizeof(dep_map));
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (mazeA[i][j] == 'Z') {
                bfs_expand(i, j, false);
            }
        }
    }
    memcpy(dep_map, dist_map, sizeof(dist_map));

    int node_cnt = 1;
    S = 0;
    T = 1;

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (mazeA[i][j] > '0' && mazeA[i][j] <= '9') {
                node_ids[i][j] = ++node_cnt;
                link_nodes(S, node_ids[i][j], mazeA[i][j] - '0');
            }
            if (mazeB[i][j] > '0' && mazeB[i][j] <= '9') {
                sink_ids[i][j] = ++node_cnt;
                link_nodes(sink_ids[i][j], T, mazeB[i][j] - '0');
            }
        }
    }

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (node_ids[i][j]) {
                bfs_expand(i, j, true);
            }
        }
    }

    int max_flow = 0;
    while (level_bfs()) {
        vector<int> lvl(MAXNODES, 0);
        lvl[S] = 1;

        function<int(int,int)> dfs = [&](int u, int f) -> int {
            if (u == T) return f;
            for (int& i = ptr[u]; i < graph[u].size(); ++i) {
                auto& e = graph[u][i];
                if (lvl[e.to] == 0 && e.cap > 0 && lvl[e.to] == lvl[u] + 1) {
                    int pushed = dfs(e.to, min(f, e.cap));
                    if (pushed) {
                        e.cap -= pushed;
                        graph[e.to][e.rev_idx].cap += pushed;
                        return pushed;
                    }
                }
            }
            return 0;
        };

        while (int pushed = dfs(S, INF_VAL)) {
            max_flow += pushed;
        }
    }

    cout << max_flow << endl;
    return 0;
}
